/* Service worker: makes the app installable and usable offline.
   - Same-origin files are precached on install (the list below is generated by tools/build_sw.py).
   - vendor/ and assets/ are cache-first (they never change between releases).
   - Everything else is network-first, so a fresh deploy is picked up as soon as you are online.
   - The OCR engine and language data come from a CDN the first time; they are kept in a separate cache so OCR keeps working offline.
   - Everything else cross-origin (web fonts have their own cache in the page, verification portals, …) is left alone. */
const CDN_CACHE = 'chumis-cdn-v1';
const CDN_HOSTS = ['cdn.jsdelivr.net', 'tessdata.projectnaptha.com'];
const VERSION = 'f38b1fe390da';
const CACHE = 'chumis-pdf-editor-' + VERSION;
const PRECACHE = ["app.html", "index.html", "privacy.html", "terms.html", "disclaimer.html", "licenses.html", "404.html", "manifest.webmanifest", "js/annots.js", "js/bake.js", "js/combine.js", "js/config.js", "js/convert.js", "js/create.js", "js/doc.js", "js/docview.js", "js/extract.js", "js/fieldmark.js", "js/fontpicker.js", "js/fonts.js", "js/home.js", "js/icons.js", "js/landing.js", "js/layout.js", "js/main.js", "js/ocr.js", "js/offline.js", "js/organize.js", "js/pagetools.js", "js/pdffont.js", "js/pdfio.js", "js/pwa.js", "js/revocation.js", "js/segfit.js", "js/sigcheck.js", "js/sign.js", "js/signatures.js", "js/trustbundle.js", "js/ttf.js", "js/ui.js", "js/validators.js", "js/verify.js", "js/viewer.js", "css/app.css", "css/components.css", "css/site.css", "css/theme.css", "vendor/fonts/poppins-400.ttf", "vendor/fonts/poppins-400i.ttf", "vendor/fonts/poppins-700.ttf", "vendor/fonts/poppins-700i.ttf", "vendor/jszip.min.js", "vendor/licenses/LICENSE_JBIG2", "vendor/licenses/LICENSE_OPENJPEG", "vendor/licenses/LICENSE_PDFJS_JBIG2", "vendor/licenses/LICENSE_PDFJS_OPENJPEG", "vendor/licenses/LICENSE_PDFJS_QCMS", "vendor/licenses/LICENSE_QCMS", "vendor/licenses/OFL-fonts.txt", "vendor/licenses/jszip-LICENSE.md", "vendor/licenses/pdf-lib-LICENSE.md", "vendor/licenses/pdfjs-LICENSE.txt", "vendor/licenses/pptxgenjs-LICENSE.txt", "vendor/pdf-lib.min.js", "vendor/pdfjs/LICENSE", "vendor/pdfjs/pdf.min.mjs", "vendor/pdfjs/pdf.worker.min.mjs", "vendor/pdfjs/standard_fonts/FoxitDingbats.pfb", "vendor/pdfjs/standard_fonts/FoxitFixed.pfb", "vendor/pdfjs/standard_fonts/FoxitFixedBold.pfb", "vendor/pdfjs/standard_fonts/FoxitFixedBoldItalic.pfb", "vendor/pdfjs/standard_fonts/FoxitFixedItalic.pfb", "vendor/pdfjs/standard_fonts/FoxitSerif.pfb", "vendor/pdfjs/standard_fonts/FoxitSerifBold.pfb", "vendor/pdfjs/standard_fonts/FoxitSerifBoldItalic.pfb", "vendor/pdfjs/standard_fonts/FoxitSerifItalic.pfb", "vendor/pdfjs/standard_fonts/FoxitSymbol.pfb", "vendor/pdfjs/standard_fonts/LICENSE_FOXIT", "vendor/pdfjs/standard_fonts/LICENSE_LIBERATION", "vendor/pdfjs/standard_fonts/LiberationSans-Bold.ttf", "vendor/pdfjs/standard_fonts/LiberationSans-BoldItalic.ttf", "vendor/pdfjs/standard_fonts/LiberationSans-Italic.ttf", "vendor/pdfjs/standard_fonts/LiberationSans-Regular.ttf", "vendor/pdfjs/wasm/LICENSE_JBIG2", "vendor/pdfjs/wasm/LICENSE_OPENJPEG", "vendor/pdfjs/wasm/LICENSE_PDFJS_JBIG2", "vendor/pdfjs/wasm/LICENSE_PDFJS_OPENJPEG", "vendor/pdfjs/wasm/LICENSE_PDFJS_QCMS", "vendor/pdfjs/wasm/LICENSE_QCMS", "vendor/pdfjs/wasm/jbig2.wasm", "vendor/pdfjs/wasm/jbig2_nowasm_fallback.js", "vendor/pdfjs/wasm/openjpeg.wasm", "vendor/pdfjs/wasm/openjpeg_nowasm_fallback.js", "vendor/pdfjs/wasm/qcms_bg.wasm", "vendor/pdfjs/wasm/quickjs-eval.js", "vendor/pdfjs/wasm/quickjs-eval.wasm", "vendor/pptxgen.bundle.js", "vendor/trust/india-pki.json", "assets/apple-touch-icon.png", "assets/favicon.svg", "assets/icon-192.png", "assets/icon-512.png", "assets/logo.svg", "assets/maskable-512.png", "assets/og-image.png"];

self.addEventListener('install', event => {
  event.waitUntil((async () => {
    const cache = await caches.open(CACHE);
    await Promise.all(PRECACHE.map(url => cache.add(new Request(url, { cache: 'reload' })).catch(() => null)));
    await self.skipWaiting();
  })());
});

self.addEventListener('activate', event => {
  event.waitUntil((async () => {
    for (const key of await caches.keys()) if (key.startsWith('chumis-pdf-editor-') && key !== CACHE) await caches.delete(key);
    await self.clients.claim();
  })());
});

self.addEventListener('fetch', event => {
  const req = event.request;
  if (req.method !== 'GET') return;
  const url = new URL(req.url);
  if (url.origin !== self.location.origin) {
    if (!CDN_HOSTS.includes(url.hostname) || /\/(fontsource|@fontsource)\//.test(url.pathname)) return;
    event.respondWith((async () => {
      const cache = await caches.open(CDN_CACHE), hit = await cache.match(req);
      if (hit) return hit;
      const res = await fetch(req);
      if (res && (res.ok || res.type === 'opaque')) cache.put(req, res.clone()).catch(() => {});
      return res;
    })());
    return;
  }
  const scope = new URL(self.registration.scope).pathname;
  const path = url.pathname.slice(scope.length);
  const immutable = path.startsWith('vendor/') || path.startsWith('assets/');
  event.respondWith((async () => {
    const cache = await caches.open(CACHE);
    if (immutable) {
      const hit = await cache.match(req, { ignoreSearch: true });
      if (hit) return hit;
    }
    try {
      const res = await fetch(req);
      if (res && res.ok && res.type === 'basic') cache.put(req, res.clone());
      return res;
    } catch (err) {
      const hit = await cache.match(req, { ignoreSearch: true });
      if (hit) return hit;
      if (req.mode === 'navigate') return (await cache.match('app.html')) || (await cache.match('index.html')) || Response.error();
      return Response.error();
    }
  })());
});
